css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .texto-box{border: 2px solid var(--bosque); border-radius: 12px;
      padding: 12px 14px; margin-bottom: 12px;
      width: 100%; box-sizing: border-box;}
.mz .texto-parrafo{font-size: 18px; font-weight: 600; line-height: 1.65;}
.mz .preguntas-lista{display: flex; flex-direction: column; gap: 9px; margin-bottom: 12px;}
.mz .pregunta-item{display: flex; flex-direction: column; gap: 3px;}
.mz .pregunta-texto{font-size: 17px; font-weight: 700;}
.mz .respuesta-linea{border-bottom: 1.5px solid var(--bosque); height: 22px; width: 100%;}
.mz .vocab-lista{display: flex; flex-direction: column; gap: 11px;}
.mz .vocab-item{display: flex; align-items: flex-end; gap: 10px;}
.mz .vocab-palabra{font-size: 17px; font-weight: 700; white-space: nowrap;}
.mz .vocab-flecha{font-size: 17px; font-weight: 700;}
.mz .vocab-respuesta{flex: 1; border-bottom: 1.5px solid var(--bosque); height: 22px;}
.mz .txt-flex{flex: 1 1 auto; min-width: 0;}
.mz .texto-parrafo{line-height: 1.725 !important;}
